public class Hooks {

    @BeforeAll
    public static void beforeAll() {
        System.out.println("Once before the whole run");
    }

    // Directional and unconditional: every scenario
    @Before(order = 0)
    public void logStart(Scenario scenario) {
        System.out.println("Starting: " + scenario.getName());
    }

    // Conditional (tagged): only scenarios tagged @ui
    @Before(value = "@ui", order = 1)
    public void startBrowser() {
        DriverManager.setDriver(new ChromeDriver());
    }

    @Before("@api and not @public")
    public void fetchToken() {
        // obtain an access token for secured API scenarios
    }

    @AfterStep("@ui")
    public void afterEachStep(Scenario scenario) {
        // optional: screenshot after each step
    }

    @After(value = "@ui", order = 1)       // higher order runs first for @After
    public void closeBrowser(Scenario scenario) {
        if (scenario.isFailed()) {
            byte[] image = ((TakesScreenshot) DriverManager.getDriver())
                    .getScreenshotAs(OutputType.BYTES);
            scenario.attach(image, "image/png", "failure");
        }
        DriverManager.unload();
    }

    @AfterAll
    public static void afterAll() {
        System.out.println("Once after the whole run");
    }
}

public class Hooks {
    // Thread-safe record of features already initialised
    private static final Set<String> INITIALISED_FEATURES = ConcurrentHashMap.newKeySet();

    // Once for the entire run
    @BeforeAll
    public static void globalSetup() {
        System.out.println("Load configuration, start mock server");
    }

    // Once per feature file: runs only for the first scenario of each feature
    @Before(order = 0)
    public void oncePerFeature(Scenario scenario) {
        String featureUri = scenario.getUri().toString();
        if (INITIALISED_FEATURES.add(featureUri)) {          // true only the first time
            System.out.println("One-time setup for " + featureUri);
        }
    }

    // Before and after every scenario
    @Before(order = 1)
    public void beforeScenario() {
        DriverManager.setDriver(new ChromeDriver());
    }

    @After
    public void afterScenario(Scenario scenario) {
        DriverManager.unload();
    }

    // Once after the entire run
    @AfterAll
    public static void globalTeardown() {
        System.out.println("Delete seeded data, stop mock server");
    }
}

// Shared context: one instance per scenario, created by PicoContainer
public class TestContext {
    private final WebDriver driver = DriverFactory.create();
    private final Map<String, Object> data = new HashMap<>();

    public WebDriver getDriver() { return driver; }
    public void set(String key, Object value) { data.put(key, value); }
    public <T> T get(String key, Class<T> type) { return type.cast(data.get(key)); }
}

public class CheckoutSteps {
    private final TestContext context;

    public CheckoutSteps(TestContext context) {       // injected
        this.context = context;
    }

    @When("the user places the order")
    public void placeOrder() {
        String orderId = new CheckoutPage(context.getDriver()).placeOrderAndGetId();
        context.set("orderId", orderId);
    }
}

public class OrderHistorySteps {
    private final TestContext context;

    public OrderHistorySteps(TestContext context) {   // same instance as above
        this.context = context;
    }

    @Then("the order appears in the order history")
    public void verifyOrder() {
        String orderId = context.get("orderId", String.class);
        Assert.assertTrue(new OrderHistoryPage(context.getDriver()).contains(orderId));
    }
}

